import { z } from "zod";
import { addDays, daysBetween, todayIST } from "./dates";
import { findLocation } from "./locations";

export { addDays, daysBetween };

/**
 * Weather for the event, from the free Open-Meteo service (no key needed).
 * - Within 16 days: the real daily forecast.
 * - Further away: the usual weather, worked out from what actually happened on
 *   the same dates over the past 10 years.
 * Numbers come straight from the weather data; nothing is generated by AI.
 */

export const FORECAST_DAYS = 16;
export const PAST_YEARS = 10;
/** Days either side of each event day used for the usual weather. */
const WINDOW = 3;
/** A day with at least this much rain (mm) counts as a rainy day. */
const RAINY_MM = 1;

export const WeatherRequestSchema = z.object({
  city: z.string().trim().min(1).max(80),
  date: z
    .string()
    .regex(/^\d{4}-\d{2}-\d{2}$/)
    .refine((v) => !Number.isNaN(Date.parse(`${v}T00:00:00Z`))),
  days: z.number().int().min(1).max(7).default(1),
});
export type WeatherRequest = z.infer<typeof WeatherRequestSchema>;

export interface WeatherDay {
  date: string;
  min: number;
  max: number;
  /** Forecast: chance of rain 0–100. */
  rainChance: number | null;
  /** WMO weather code (forecast only). */
  code: number | null;
}

export type RainLevel = "low" | "some" | "likely";

export interface WeatherSummary {
  kind: "forecast" | "usual" | "none";
  place: string;
  min: number;
  max: number;
  rain: RainLevel;
  /** Usual: share of past days (0–1) with rain. */
  rainyShare: number | null;
  /** Usual: number of past years the figures are based on. */
  years: number;
  days: WeatherDay[];
  /** Usual: the date a real forecast becomes available. */
  forecastFrom: string | null;
}

const NONE: WeatherSummary = {
  kind: "none",
  place: "",
  min: 0,
  max: 0,
  rain: "low",
  rainyShare: null,
  years: 0,
  days: [],
  forecastFrom: null,
};

export function rainLevel(share: number): RainLevel {
  if (share >= 0.5) return "likely";
  if (share >= 0.2) return "some";
  return "low";
}

/** Short words and an emoji for a WMO weather code. */
export function describeCode(code: number | null): { label: string; icon: string } {
  if (code === null) return { label: "", icon: "🌤️" };
  if (code === 0) return { label: "clear", icon: "☀️" };
  if (code <= 2) return { label: "partly cloudy", icon: "🌤️" };
  if (code === 3) return { label: "cloudy", icon: "☁️" };
  if (code === 45 || code === 48) return { label: "foggy", icon: "🌫️" };
  if (code >= 51 && code <= 57) return { label: "drizzle", icon: "🌦️" };
  if (code >= 61 && code <= 67) return { label: "rain", icon: "🌧️" };
  if (code >= 71 && code <= 77) return { label: "snow", icon: "🌨️" };
  if (code >= 80 && code <= 82) return { label: "showers", icon: "🌦️" };
  if (code >= 95) return { label: "thunderstorms", icon: "⛈️" };
  return { label: "", icon: "🌤️" };
}

/** One practical line for the host, worked out from the numbers. */
export function weatherTip(w: Pick<WeatherSummary, "min" | "max" | "rain">): string {
  if (w.rain === "likely") return "Keep a covered or indoor option, and a tent plan for anything outdoors.";
  if (w.max >= 36) return "Very hot. Plan shade, plenty of water and evening timings for outdoor parts.";
  if (w.rain === "some") return "Some chance of rain. Keep a backup cover for outdoor parts.";
  if (w.min <= 12) return "Cool evenings. Keep shawls or heaters for anything outdoors at night.";
  return "Pleasant weather is expected. Outdoor parts should work well.";
}

interface DailyData {
  time?: string[];
  temperature_2m_max?: (number | null)[];
  temperature_2m_min?: (number | null)[];
  precipitation_sum?: (number | null)[];
  precipitation_probability_max?: (number | null)[];
  weather_code?: (number | null)[];
}

async function getDaily(url: string, fetcher: typeof fetch, timeoutMs: number): Promise<DailyData | null> {
  try {
    const res = await fetcher(url, { signal: AbortSignal.timeout(timeoutMs) });
    if (!res.ok) return null;
    const data = (await res.json()) as { daily?: DailyData };
    return data.daily ?? null;
  } catch {
    return null;
  }
}

const round = (n: number) => Math.round(n);

const cache = new Map<string, { at: number; value: WeatherSummary }>();
const FORECAST_TTL = 3 * 60 * 60 * 1000;
const USUAL_TTL = 7 * 24 * 60 * 60 * 1000;

export function clearWeatherCache(): void {
  cache.clear();
}

/** Same month and day in an earlier year (29 Feb becomes 28 Feb). */
function sameDayIn(iso: string, year: number): string {
  const [, m, d] = iso.split("-").map(Number);
  const day = m === 2 && d === 29 ? 28 : d;
  return `${year}-${String(m).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

export async function getWeather(
  req: WeatherRequest,
  {
    fetcher = fetch,
    now = new Date(),
    timeoutMs = 6000,
  }: { fetcher?: typeof fetch; now?: Date; timeoutMs?: number } = {},
): Promise<WeatherSummary> {
  const today = todayIST(now);
  const days = req.days ?? 1;
  const last = addDays(req.date, days - 1);
  if (daysBetween(today, last) < 0) return NONE; // the event is over

  const key = `${req.city.trim().toLowerCase()}|${req.date}|${days}|${today}`;
  const hit = cache.get(key);
  if (hit && now.getTime() - hit.at < (hit.value.kind === "forecast" ? FORECAST_TTL : USUAL_TTL)) return hit.value;

  const place = await findLocation(req.city, fetcher);
  if (!place) return NONE;
  const where = `latitude=${place.latitude.toFixed(3)}&longitude=${place.longitude.toFixed(3)}&timezone=${encodeURIComponent(
    place.timeZone,
  )}`;

  let value: WeatherSummary = NONE;
  if (daysBetween(today, last) < FORECAST_DAYS) {
    const daily = await getDaily(
      `https://api.open-meteo.com/v1/forecast?${where}&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,weather_code&forecast_days=${FORECAST_DAYS}`,
      fetcher,
      timeoutMs,
    );
    value = daily ? summariseForecast(daily, req.date, last, place.name) : NONE;
  } else {
    const year = Number(req.date.slice(0, 4));
    const thisYear = Number(today.slice(0, 4));
    // Only years whose dates are fully in the past.
    const endYear = Math.min(year - 1, thisYear - 1);
    const startYear = endYear - PAST_YEARS + 1;
    const start = addDays(sameDayIn(req.date, startYear), -WINDOW);
    const end = addDays(sameDayIn(last, endYear), WINDOW);
    const daily = await getDaily(
      `https://archive-api.open-meteo.com/v1/archive?${where}&start_date=${start}&end_date=${end}&daily=temperature_2m_max,temperature_2m_min,precipitation_sum`,
      fetcher,
      timeoutMs,
    );
    value = daily
      ? summariseUsual(daily, req.date, days, startYear, endYear, place.name, addDays(last, -(FORECAST_DAYS - 1)))
      : NONE;
  }
  if (value.kind !== "none") cache.set(key, { at: now.getTime(), value });
  return value;
}

export function summariseForecast(daily: DailyData, first: string, last: string, place: string): WeatherSummary {
  const out: WeatherDay[] = [];
  (daily.time ?? []).forEach((date, i) => {
    if (date < first || date > last) return;
    const max = daily.temperature_2m_max?.[i];
    const min = daily.temperature_2m_min?.[i];
    if (typeof max !== "number" || typeof min !== "number") return;
    out.push({
      date,
      min: round(min),
      max: round(max),
      rainChance: daily.precipitation_probability_max?.[i] ?? null,
      code: daily.weather_code?.[i] ?? null,
    });
  });
  if (out.length === 0) return NONE;
  const top = Math.max(...out.map((d) => d.rainChance ?? 0));
  return {
    kind: "forecast",
    place,
    min: Math.min(...out.map((d) => d.min)),
    max: Math.max(...out.map((d) => d.max)),
    rain: rainLevel(top / 100),
    rainyShare: null,
    years: 0,
    days: out,
    forecastFrom: null,
  };
}

export function summariseUsual(
  daily: DailyData,
  date: string,
  days: number,
  startYear: number,
  endYear: number,
  place: string,
  forecastFrom: string,
): WeatherSummary {
  // The event days (with a few days either side) in each past year.
  const wanted = new Map<string, number>();
  for (let y = startYear; y <= endYear; y++) {
    const first = sameDayIn(date, y);
    for (let i = -WINDOW; i < days + WINDOW; i++) wanted.set(addDays(first, i), y);
  }
  const maxes: number[] = [];
  const mins: number[] = [];
  let measured = 0;
  let rainy = 0;
  const years = new Set<number>();
  (daily.time ?? []).forEach((d, i) => {
    const year = wanted.get(d);
    if (year === undefined) return;
    const max = daily.temperature_2m_max?.[i];
    const min = daily.temperature_2m_min?.[i];
    const rain = daily.precipitation_sum?.[i];
    if (typeof max === "number") maxes.push(max);
    if (typeof min === "number") mins.push(min);
    if (typeof rain === "number") {
      measured++;
      if (rain >= RAINY_MM) rainy++;
    }
    years.add(year);
  });
  if (maxes.length === 0 || mins.length === 0) return NONE;
  const avg = (xs: number[]) => xs.reduce((a, b) => a + b, 0) / xs.length;
  const share = measured ? rainy / measured : 0;
  return {
    kind: "usual",
    place,
    min: round(avg(mins)),
    max: round(avg(maxes)),
    rain: rainLevel(share),
    rainyShare: Math.round(share * 100) / 100,
    years: years.size,
    days: [],
    forecastFrom,
  };
}
